import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/MacBookAir.html","title":"MacBookAir","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.78,"words":535},"filePathRelative":"MacBookAir.md"}`),a={name:`MacBookAir.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="macbookair" tabindex="-1"><a class="header-anchor" href="#macbookair"><span>MacBookAir</span></a></h1><ul><li><a href="./ノートPC.html">ノートPC</a></li><li><a href="./Mac.html">Mac</a></li></ul><h2 id="mac-book-air-15インチ、2025年モデル" tabindex="-1"><a class="header-anchor" href="#mac-book-air-15インチ、2025年モデル"><span>Mac Book Air 15インチ、2025年モデル</span></a></h2><ul><li>15インチ</li><li>M4</li><li>16GBメモリ</li><li>512GB SSD</li><li>70W MagSafe3充電器</li><li><a href="https://support.apple.com/ja-jp/122210" target="_blank" rel="noopener noreferrer">MacBook Air (15インチ, M4, 2025) - 技術仕様 - Apple サポート (日本)</a></li></ul><p>22万8800円。</p><h3 id="購入-2025-10-26-日" tabindex="-1"><a class="header-anchor" href="#購入-2025-10-26-日"><span>購入 2025-10-26 (日)</span></a></h3><p>仕事で使ってたインテルMac Book Pro16 インチが、最近のアップデートで（現在Sequoia 15.7.1、もう少し前から）くらいからめっちゃビルドが遅くなって、 しかもタッチIDがなんかバグってロック画面でタッチ認証が出来ない事がめっちゃ多いという不具合も出てきて、 ストレスがだいぶ上がってきた。 アップデートで遅くなるのはIntel Macで良く見かける話なので、 Apple Siliconはどうなのかなぁ、と思っていた。</p><p>また、購入当時はあまり移動しないので自宅の机の上の作業環境重視でMac Book Proにしたが、 スクーターに乗り換えた都合でスクーターでも運びやすいのがいいなぁ、とか、そこそこ持ち運ぶ事も出てきたので、 もうちょっと軽い奴が欲しくなってきてもいた。</p><p>そんな折、Mac Book Airに15インチが出た、という事で、現状の16インチより少し小さくなるだけなので、試してみるか、という気分になる。</p><p>バッテリの保ちが凄く良いという噂も聞いていたし、ビルド目的でどうなのか気になっていたので一回は使ってみたかった。</p><p>到着予定は11/1〜3のあたり、という事で一週間くらいか。</p><p>メモリについては16GBにした。一番重要なビルドが、そもそもコアの数に比例してメモリを消費するもので、 コア数が10しか無い（しかもPコアは4つ）なら16GBでいいか、という事で。現状も16GBで、 ビルド時にメモリが不足している感じでは無いので。 正直こんなコア少なくて大丈夫なの？という気もするが、M1が出た頃、ビルド時間はIntel Macよりも少し早い、という比較を結構見たので、 M4ならだいぶ早くなるのを期待したい。</p><p>SSDは現状は1TBでちょくちょく溢れているが、たかが512GB追加するだけで+３万円との事で、512GBにする。 まぁ実際512GBは生きてはいける。</p><h3 id="到着-2025-11-02-日" tabindex="-1"><a class="header-anchor" href="#到着-2025-11-02-日"><span>到着 2025-11-02 (日)</span></a></h3><p>第一印象、重っ！まじでこんな重いの？</p><p>移行アシスタントの出来も悪くてかなり萎えたが、それが終わった後は結構いい感じだ。 キーボードはむしろMacBook Proよりも良い気がする。画面も思ったほど小さくない。バッテリの保ちも良い。</p><h3 id="ビルドはまぁまぁ、バッテリのもちは驚異的-2025-11-03-月" tabindex="-1"><a class="header-anchor" href="#ビルドはまぁまぁ、バッテリのもちは驚異的-2025-11-03-月"><span>ビルドはまぁまぁ、バッテリのもちは驚異的 2025-11-03 (月)</span></a></h3><p>ようやくビルド環境を整えて仕事のコードなどをビルドしてみた。速さは驚くほど早いという訳では無いが、まぁまぁ早い。満足ではある。 Intel Mac Book Proがめちゃ遅くなったのを思うと、買って良かった。</p><p>重さも一晩経って慣れてくると、そこまででも無い気はしてきた。 見た目の印象より重いのとサイズが薄くて大きいせいで端を持つとテコの原理で手が結構きつい、というのの相乗効果で実際より重く感じていた部分はある。</p><p>ビルドがそれなりに早いと印象がグッと良くなるね。 だんだんと買って良かったという気分が高まってきた。</p><h3 id="移行作業-2025-11-04-火" tabindex="-1"><a class="header-anchor" href="#移行作業-2025-11-04-火"><span>移行作業 2025-11-04 (火)</span></a></h3><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> DotnetCoreを入れる</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-1"><a href="./guash.html">guash</a>と<a href="./htmnix.html">htmnix</a>をビルド</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 雑用スクリプトを持ってくる</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> golangを入れてmdimgrを持ってくる</label></li></ul><p>ノリで<a href="./Syncthing.html">Syncthing</a>のディレクトリを変えたら色々ハードコードしているスクリプトが全修正になって無駄に手間がかかる。 ただ元々の場所が少しおかしかったので、あんまりそれに依存したものが多いのも良くないよな、ということで、やっておくべき作業だった気はする。</p><h3 id="しばらく使ってみての感想、結構いいね-2025-11-11-火" tabindex="-1"><a class="header-anchor" href="#しばらく使ってみての感想、結構いいね-2025-11-11-火"><span>しばらく使ってみての感想、結構いいね！ 2025-11-11 (火)</span></a></h3><p>当初は予想以上に重くて動揺していたが、半分くらいは思ったより重い事から来る反動のようなもので、最初からある程度重さを覚悟して持てばそうでも無い、と感じるようになった。端を片手で持とうとするときつい。 そしてカバンに入れればそこまで重く感じない。カバンに入れるとこのくらいならいいか、という重さに感じられる。</p><p>熱くならないのでヒザの上テーブル無しで膝の上で作業できるのはいいね。 バッテリのもちも家の中で電源つけずに作業しているには十分で、半日くらいの作業ではバッテリが無くなる事は無い。 ノートPCを片付けようという気分になった時についでに充電すれば十分、という感じで、 ほとんど電源を意識せずに家の中のどこでも作業出来るようになった。これは快適。</p><p>電源が左だけでMag Safe 3と言われて最初はかなり萎えたが、あんまり充電しながら使いたいという感じでは無いので当初思った程は嫌でもなかった。</p><p>ビルドの速度も結構早い。コア数が無いのでめちゃくちゃ早いと驚く感じでは無いが、シングルコアあたりの速さは相当のものなので、 全体的には結構早く終わる。最近めちゃ遅くなったインテル MacBook Proとは雲泥の差。 ただRyzen Windowsと比べて早いという気はそんなにしてないが、このくらいになるとそんなに不満も無いのでわざわざ測ろうという気も起こらないな。 そのうち気が向いたらちゃんと測ってみるかもしれないが。</p><p>全体的には結構満足するようになった。第一印象よりはだいぶ改善されて、当初期待していたくらいの使い心地になった気はする。</p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};